namespace ScreenText {
    public static class Program {
        [DllImport("shcore.dll")] static extern int SetProcessDpiAwareness(int value);
        [DllImport("user32.dll")] static extern bool AllowSetForegroundWindow(int processId);
        public const string ActivationEventName=@"Local\ScreenTextTranslate-activate-v1";
        public static RegisteredWaitHandle ListenForActivation(MainForm form,WaitHandle signal){return ThreadPool.RegisterWaitForSingleObject(signal,(state,timedOut)=>{try{form.BeginInvoke(new Action(form.ActivateExistingWindow));}catch(InvalidOperationException){}},null,Timeout.Infinite,false);}
        [STAThread] public static void Main(string[] args) {
            try { SetProcessDpiAwareness(2); } catch { }
            Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false);
            if(args.Length>1&&args[0]=="--tray-preview"){using(var form=new MainForm(true)){form.MakeTrayPreview(args[1],args.Length>2&&args[2]=="light");}return;}
            if (args.Length > 1 && args[0] == "--preview") {
                using (var form = new MainForm(true)) { if(args.Length>3&&args[3]=="small")form.Size=form.MinimumSize;if(args.Length>3&&args[3]=="settings")form.MakeSettingsPreview(args[1],args.Length>2 && args[2]=="light",args.Length>4?args[4]:"Appearance",args.Length>5?args[5]:"Green",args.Length>6&&args[6]=="open",args.Length>7?args[7]:"");else form.MakePreview(args[1],args.Length>2 && args[2]=="light",args.Length>4?args[4]:"Green"); }
                return;
            }
            // Retired live probes must never spend account usage from a test-looking switch.
            if(args.Length>0&&(args[0]=="--self-test"||args[0]=="--image-test")){Environment.ExitCode=2;return;}
            bool startup=args.Any(arg=>arg.Equals("--startup",StringComparison.OrdinalIgnoreCase));
            bool first;
            using (var mutex = new Mutex(true, "Local\\ScreenTextTranslate-v1", out first)) {
                using(var activation=new EventWaitHandle(false,EventResetMode.AutoReset,ActivationEventName)){
                    if(!first){if(!startup){AllowSetForegroundWindow(-1);activation.Set();}return;}
                    using(var form=new MainForm(false,startup)){var listener=ListenForActivation(form,activation);try{Application.Run(form);}finally{listener.Unregister(null);}}
                }
            }
        }
    }

    public class StartupRegistration {
        public const string RunKey=@"Software\Microsoft\Windows\CurrentVersion\Run";
        readonly string executable,keyPath;
        public StartupRegistration(string appPath=null,string registryPath=RunKey){executable=Path.GetFullPath(appPath??Application.ExecutablePath);keyPath=registryPath;}
        public string Command{get{return Backend.Quote(executable)+" --startup";}}
        public string RegisteredCommand{get{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(keyPath)){return key==null?null:key.GetValue("ScreenText") as string;}}}
        public bool Enabled{get{return String.Equals(RegisteredCommand,Command,StringComparison.OrdinalIgnoreCase);}}
        public void SetEnabled(bool enabled){
            if(enabled){using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(keyPath)){key.SetValue("ScreenText",Command,Microsoft.Win32.RegistryValueKind.String);}}
            else using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(keyPath,true)){if(key!=null)key.DeleteValue("ScreenText",false);}
            if(Enabled!=enabled)throw new IOException("Windows could not confirm the startup change.");
        }
    }

