        void CaptureShortcutKeyDown(object sender,KeyEventArgs e){
            if(e.KeyCode==Keys.Tab&&e.Modifiers==Keys.None)return;e.SuppressKeyPress=e.Handled=true;
            if(e.KeyCode==Keys.Escape){pendingModifiers=shortcutModifiers;pendingKey=shortcutKey;shortcutInput.Text=ShortcutText(shortcutModifiers,shortcutKey);shortcutFeedback.Text="Shortcut unchanged.";return;}
            uint modifiers=(uint)((e.Alt?1:0)|(e.Control?2:0)|(e.Shift?4:0)),key=(uint)e.KeyCode;
            if(e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.LControlKey||e.KeyCode==Keys.RControlKey)modifiers|=2;
            if(e.KeyCode==Keys.Menu||e.KeyCode==Keys.LMenu||e.KeyCode==Keys.RMenu)modifiers|=1;
            if(e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.LShiftKey||e.KeyCode==Keys.RShiftKey)modifiers|=4;
            bool modifierKey=e.KeyCode==Keys.ControlKey||e.KeyCode==Keys.LControlKey||e.KeyCode==Keys.RControlKey||e.KeyCode==Keys.Menu||e.KeyCode==Keys.LMenu||e.KeyCode==Keys.RMenu||e.KeyCode==Keys.ShiftKey||e.KeyCode==Keys.LShiftKey||e.KeyCode==Keys.RShiftKey;
            if(modifierKey){pendingModifiers=modifiers;pendingKey=0;shortcutInput.Text=ShortcutText(modifiers,0)+"…";shortcutFeedback.Text="Keep holding the modifiers and press a letter, number or function key.";return;}
            if(!ValidShortcut(modifiers,key)){shortcutFeedback.Text="Use Ctrl/Alt with a letter or number, or F1–F24.";return;}
            pendingModifiers=modifiers;pendingKey=key;shortcutInput.Text=ShortcutText(modifiers,key);shortcutFeedback.Text="Select Apply to save and activate this shortcut.";
        }
        static bool ValidShortcut(uint modifiers,uint key){return (modifiers&~7u)==0&&((key>=0x30&&key<=0x39)||(key>=0x41&&key<=0x5A)||(key>=0x70&&key<=0x87))&&((modifiers&3)!=0||(key>=0x70&&key<=0x87));}
        static string ShortcutText(uint modifiers,uint key){return ((modifiers&2)!=0?"Ctrl + ":"")+((modifiers&1)!=0?"Alt + ":"")+((modifiers&4)!=0?"Shift + ":"")+(key==0?"":key>=0x30&&key<=0x39?((char)key).ToString():((Keys)key).ToString());}
        void LoadShortcut(){var parts=ReadPreference("screenshot-shortcut.txt").Split('|');uint mods,key;if(parts.Length==2&&UInt32.TryParse(parts[0],out mods)&&UInt32.TryParse(parts[1],out key)&&ValidShortcut(mods,key)){shortcutModifiers=mods;shortcutKey=key;}pendingModifiers=shortcutModifiers;pendingKey=shortcutKey;}
        bool ApplyShortcut(uint modifiers,uint key){
            if(!ValidShortcut(modifiers,key)){shortcutFeedback.Text="Use Ctrl or Alt with a letter or number, or use a function key.";return false;}
