        bool TranslationNeedsUpdate(){return result.Text.Length>0&&translationSourceSnapshot!=null&&!String.Equals(source.Text,translationSourceSnapshot,StringComparison.Ordinal);}
        void UpdateTranslationState(){
            // Native replacement/paste can briefly report an empty value before inserting the new text.
