            if(result.Text.Length==0){hasTranslationResult=false;translationSourceSnapshot=translationTargetSnapshot=null;resultTitle.Text="Translation";result.RightToLeft=RightToLeft.No;}else{if(translationSourceSnapshot==null)translationSourceSnapshot=source.Text;if(translationTargetSnapshot==null)translationTargetSnapshot=currentTarget;}
            UpdateResultEditability();UpdateWorkspaceConnection();string change=TranslationChangeNote();bool changed=change.Length>0;resultCount.Text=result.Text.Length==0?"Uses shared Work/Codex allowance":result.Text.Length.ToString("N0")+" characters · "+(changed?change:"ready to copy");copyResult.Enabled=!String.IsNullOrWhiteSpace(result.Text);workspaceHints.SetToolTip(resultCount,changed?"The source or selected target has changed. The previous translation is kept until you translate again.":"Copy or edit your translation.");
        }
