            else if(control is Button){var b=(Button)control;bool primary=tag=="primary",selected=tag=="selected",ghost=tag=="ghost";b.BackColor=primary?blue:selected?Blend(surface,blue,dark?.18:.10):inherited;b.ForeColor=primary?(dark?Color.FromArgb(18,24,32):Color.White):selected?blue:ink;b.FlatAppearance.BorderColor=primary?blue:selected?Blend(border,blue,.6):ghost?inherited:localBorder;if(b is ThemeButton){((ThemeButton)b).InactiveForeColor=Blend(inherited,ink,dark?.38:.36);((ThemeButton)b).DisabledBackColor=Blend(inherited,muted,.06);((ThemeButton)b).DisabledBorderColor=Blend(inherited,muted,.28);((ThemeButton)b).Border= !ghost;}}
            else if(control is ThemeCheckBox){var box=(ThemeCheckBox)control;box.BackColor=inherited;box.ForeColor=ink;box.AccentColor=blue;box.BorderColor=muted;box.CheckColor=dark?Color.FromArgb(18,24,32):Color.White;}
            else if(control is ShortcutCapture){var input=(ShortcutCapture)control;input.BackColor=inherited;input.ForeColor=ink;input.BorderColor=border;input.AccentColor=blue;}
            else if(control is TextBox||control is ThemeCombo||control is ListBox){control.BackColor=inherited;control.ForeColor=ink;if(control is ThemeCombo){((ThemeCombo)control).BorderColor=localBorder;((ThemeCombo)control).ArrowColor=blue;((ThemeCombo)control).SelectionColor=Blend(surface,blue,dark?.20:.12);((ThemeCombo)control).DisabledForeColor=Blend(inherited,ink,dark?.38:.36);}if(control is ListBox)try{SetWindowTheme(control.Handle,dark?"DarkMode_Explorer":null,null);}catch{}}
            else{control.BackColor=control is RoundedPanel?(tag=="translation-inactive"?Blend(surface,background,.65):tag=="extraction"?Blend(surface,blue,dark?.08:.05):surface):inherited;control.ForeColor=control is Label&&tag!="heading"?muted:ink;if(control is Label&&tag=="placeholder-detail")control.ForeColor=Blend(inherited,muted,.80);if(control is RoundedPanel)((RoundedPanel)control).BorderColor=tag=="extraction"?blue:border;}
