        public void MakePreview(string path,bool light,string color="Green"){SetAccent(color);changingTheme=true;dark=!light;themeChoice.SelectedIndex=light?1:0;changingTheme=false;source.Text="Καλημέρα! Το ChatGPT Plus/Pro λειτουργεί χωρίς API key.\r\nΠατήστε Αποθήκευση / Save changes πριν κλείσετε το παράθυρο.";SelectTranslationTarget(TranslationCatalog.Find("en"));CommitTranslationResult("Good morning! ChatGPT Plus/Pro works without an API key.\r\nClick Save changes before closing the window.",source.Text,"en","English");extractMode.SelectedIndex=1;foreach(var button in translations)button.Tag=button.Text=="English"?"selected":"secondary";resultTitle.Text="Translation · English";copyResult.Enabled=true;status.Text="Preview · sample text";using(var sample=new Bitmap(760,220))using(var g=Graphics.FromImage(sample))using(var font=new Font("Segoe UI",18)){g.Clear(Color.FromArgb(246,248,246));g.DrawString("Καλημέρα! Το ChatGPT Plus/Pro λειτουργεί\nχωρίς API key.\n\nΑποθήκευση / Save changes",font,Brushes.Black,24,20);using(var buffer=new MemoryStream()){sample.Save(buffer,ImageFormat.Png);lastImage=buffer.ToArray();}}UpdateThumbnail();UpdateImageActions();ApplyTheme();ShowInTaskbar=false;Show();Application.DoEvents();var languageLoading=EnsureOcrLanguages();var languageWait=Stopwatch.StartNew();while(!languageLoading.IsCompleted&&languageWait.ElapsedMilliseconds<8000){Application.DoEvents();Thread.Sleep(10);}using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(Point.Empty,Size));bmp.Save(path,ImageFormat.Png);}Hide();tray.Visible=false;}
        protected override void WndProc(ref Message m){if(m.Msg==0x312&&m.WParam.ToInt32()==hotkeyId){if(!busy&&Enabled)BeginInvoke(new Action(CaptureRegion));}base.WndProc(ref m);}
        static string ReadPreference(string name){try{return File.ReadAllText(Path.Combine(AppStorage.SettingsDirectory,name)).Trim();}catch{return "";}}
        void SetCurrentImage(string path,bool newImage){
            byte[] bytes;using(var image=Image.FromFile(path))using(var normalized=new Bitmap(image))using(var stream=new MemoryStream()){normalized.Save(stream,ImageFormat.Png);bytes=stream.ToArray();}
            lastImage=bytes;imageWarning="";
            if(newImage){lastImagePath=null;editingPath=null;currentImageSaved=false;}else if(editingPath!=null&&String.Equals(Path.GetFullPath(path),Path.GetFullPath(editingPath),StringComparison.OrdinalIgnoreCase))currentImageSaved=false;
            UpdateThumbnail();UpdateImageActions();
            if(newImage&&autoCopyImage.Checked&&!CopyImage(false))imageWarning="Image is ready, but automatic copying failed. Use Copy to retry.";
        }
        void CleanupTemporaryImages(){
            var root=Path.GetFullPath(temporaryImageDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
            foreach(var file in temporaryImageFiles){try{var full=Path.GetFullPath(file);if(full.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(full).StartsWith("edit-",StringComparison.Ordinal))File.Delete(full);}catch{}}
            // Non-recursive: never remove unrelated editor-created files.
            try{var marker=Path.Combine(temporaryImageDirectory,".screentext-session");if(Directory.Exists(temporaryImageDirectory)&&Directory.GetFileSystemEntries(temporaryImageDirectory).All(p=>p==marker)){File.Delete(marker);Directory.Delete(temporaryImageDirectory,false);}}catch{}
        }
        static void CleanupOldTemporaryImages(){
            try{var temp=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;foreach(var directory in Directory.GetDirectories(temp,"ScreenText-editor-*"))try{
                var full=Path.GetFullPath(directory);if(!full.StartsWith(temp,StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(full),"^ScreenText-editor-[a-f0-9]{32}$")||(File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0||Directory.GetLastWriteTimeUtc(full)>DateTime.UtcNow.AddDays(-1))continue;
                var marker=Path.Combine(full,".screentext-session");if(!File.Exists(marker)||File.ReadAllText(marker)!="ScreenText temporary editor cache v1")continue;
                foreach(var file in Directory.GetFiles(full,"edit-*.png")){if(System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(file),"^edit-[a-f0-9]{32}\\.png$")&&(File.GetAttributes(file)&FileAttributes.ReparsePoint)==0)try{File.Delete(file);}catch{}}
                if(Directory.GetFileSystemEntries(full).All(p=>p==marker)){File.Delete(marker);Directory.Delete(full,false);}
            }catch{}}catch{}
        }
        string PrepareEditableImage(){
            if(lastImage==null)throw new InvalidOperationException("No image is available.");
            if(editingPath==null||!File.Exists(editingPath)){Directory.CreateDirectory(temporaryImageDirectory);File.WriteAllText(Path.Combine(temporaryImageDirectory,".screentext-session"),"ScreenText temporary editor cache v1");editingPath=Path.Combine(temporaryImageDirectory,"edit-"+Guid.NewGuid().ToString("N")+".png");File.WriteAllBytes(editingPath,lastImage);temporaryImageFiles.Add(editingPath);}return editingPath;
        }
        void SaveImageTo(string path){
            if(lastImage==null)throw new InvalidOperationException("No image is available.");
            var full=Path.GetFullPath(path);var tempRoot=Path.GetFullPath(temporaryImageDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
            if(full.StartsWith(tempRoot,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Choose a folder outside the temporary editor cache to keep this image.");
            File.WriteAllBytes(full,lastImage);lastImagePath=full;currentImageSaved=true;UpdateThumbnail();UpdateImageActions();status.Text="Image saved to "+full;
        }

        void UpdateThumbnail(){
            if(lastImage==null)return;
            using(var stream=new MemoryStream(lastImage))using(var image=Image.FromStream(stream)){
                double ratio=Math.Min(1,Math.Min(560.0/image.Width,320.0/image.Height));var next=new Bitmap(Math.Max(1,(int)(image.Width*ratio)),Math.Max(1,(int)(image.Height*ratio)));
                using(var g=Graphics.FromImage(next)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(image,0,0,next.Width,next.Height);}
                var previous=thumbnail.Image;thumbnail.Image=next;if(previous!=null)previous.Dispose();
                imageInfo.Text=image.Width+" × "+image.Height+" px"+(currentImageSaved?" · saved":" · temporary");
            }
            imagePlaceholder.Visible=false;
        }
        void UpdateImageActions(){bool hasImage=lastImage!=null;copyImageButton.Enabled=saveImageButton.Enabled=hasImage;editImageButton.Enabled=hasImage&&!busy;folderButton.Enabled=lastImagePath!=null&&File.Exists(lastImagePath);reocr.Enabled=hasImage&&!busy;}
        void ClearWorkspace(){hasTranslationResult=false;source.Clear();result.Clear();UpdateResultEditability();translationSourceSnapshot=translationTargetSnapshot=null;resultTitle.Text="Translation";lastImage=null;lastImagePath=null;editingPath=null;currentImageSaved=false;if(thumbnail.Image!=null){var old=thumbnail.Image;thumbnail.Image=null;old.Dispose();}imagePlaceholder.Visible=true;imageInfo.Text="Capture or open an image";UpdateImageActions();status.Text="Workspace cleared. Files you saved were kept.";}
        bool CopyImage(bool showStatus){
            if(lastImage==null)return false;
            try{using(var stream=new MemoryStream(lastImage))using(var decoded=Image.FromStream(stream))using(var bitmap=new Bitmap(decoded))using(var png=new MemoryStream(lastImage)){
                var data=new DataObject();data.SetData(DataFormats.Bitmap,true,bitmap);data.SetData("PNG",false,png);Clipboard.SetDataObject(data,true,3,100);
            }if(showStatus)status.Text="Image copied to clipboard.";return true;}catch{if(showStatus)status.Text="The clipboard is busy. Try copying the image again.";return false;}
        }
        void SaveImage(){if(lastImage==null)return;using(var dialog=new SaveFileDialog{Title="Save screenshot",Filter="PNG image|*.png",DefaultExt="png",AddExtension=true,FileName=lastImagePath==null?"ScreenText.png":Path.GetFileName(lastImagePath),OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{SaveImageTo(dialog.FileName);}catch(Exception ex){Notice(ex.Message,"Save image");}}}
        void ViewImage(){
            if(lastImage==null)return;
            using(var stream=new MemoryStream(lastImage))using(var image=Image.FromStream(stream))using(var bitmap=new Bitmap(image))using(var viewer=new Form{Text="Screenshot — "+image.Width+" × "+image.Height,Size=new Size(Math.Min(1100,Math.Max(620,image.Width+40)),Math.Min(800,Math.Max(420,image.Height+100))),MinimumSize=new Size(480,360),StartPosition=FormStartPosition.CenterParent,BackColor=background,Icon=Icon,KeyPreview=true}){
                var picture=new PictureBox{Image=bitmap,Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom,Padding=new Padding(16)};viewer.Controls.Add(picture);var footer=new Label{Text="Ctrl + C to copy image     ·     Esc to close",Dock=DockStyle.Bottom,Height=35,ForeColor=muted,BackColor=background,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",9)};viewer.Controls.Add(footer);viewer.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)viewer.Close();if(e.Control&&e.KeyCode==Keys.C){CopyImage(true);e.SuppressKeyPress=true;}};
                try{int enabled=dark?1:0;if(DwmSetWindowAttribute(viewer.Handle,20,ref enabled,4)!=0)DwmSetWindowAttribute(viewer.Handle,19,ref enabled,4);}catch{}viewer.ShowDialog(this);
            }
        }
        void OpenCaptureFolder(){try{var folder=lastImagePath==null?null:Path.GetDirectoryName(lastImagePath);if(folder!=null&&Directory.Exists(folder))Process.Start(new ProcessStartInfo("explorer.exe",Backend.Quote(folder)){UseShellExecute=true});}catch(Exception ex){Notice(ex.Message,"Capture folder");}}


        void Copy(string text){if(String.IsNullOrEmpty(text))return;try{Clipboard.SetText(text);status.Text="Copied to clipboard.";}catch{status.Text="The clipboard is busy. Please try again.";}}
        void SetBusy(bool value,string message){busy=value;capture.Enabled=paste.Enabled=open.Enabled=extractMode.Enabled=localMode.Enabled=codexMode.Enabled=!value;ocrLanguage.Enabled=!value&&extractMode.SelectedIndex==0;reocr.Enabled=!value&&lastImage!=null;clearText.Enabled=!value;source.ReadOnly=value;UpdateResultEditability();UpdateTranslateAction();foreach(var b in translations)b.Enabled=!value;if(moreLanguages!=null)moreLanguages.Enabled=!value;UpdateLanguageActions();UpdateTargetActions();cancel.Visible=value;cancel.Enabled=true;if(value){operation=new CancellationTokenSource();activity=message;started=DateTime.Now;timer.Start();}else{timer.Stop();if(operation!=null){operation.Dispose();operation=null;}}autoCopyImage.Enabled=defaultExtractChoice.Enabled=editorChoice.Enabled=editorBrowse.Enabled=editorRefresh.Enabled=editorArguments.Enabled=!value;UpdateRecognitionControls();UpdateStorageControls();UpdateImageActions();UpdateAiControls();status.Text=message;}
        string OcrLanguage(){return ocrLanguage.SelectedIndex>=0?((OcrOption)ocrLanguage.Items[ocrLanguage.SelectedIndex]).Tag:"system";}
        async Task RepeatExtract(){if(busy||lastImage==null)return;var p=TempImage();try{File.WriteAllBytes(p,lastImage);await ReadImage(p,true,false);}catch(Exception ex){Notice(ex.Message,"Text extraction");}finally{TransientImages.Delete(p);}}
        async Task ReadImage(string path,bool remove,bool newImage=true){
            if(busy)return;var language=OcrLanguage();bool codex=extractMode.SelectedIndex==1;SetBusy(true,codex?"Extracting with "+AiName+" · sending image…":"Extracting text on your device…");
            try{SetCurrentImage(path,newImage);if(remove&&newImage)AutoSaveCurrentImage();if(!codex){await EnsureOcrLanguages();language=OcrLanguage();ValidateOcrSelection(language);}LocalOcrResult localResult=null;var text=codex?await ExtractWithAi(path,operation.Token):(localResult=await OneOcrService.Read(path,language,languageSettings.WindowsOcrTag,operation.Token)).Text;if(closing)return;source.Text=text;SetBusy(false,(localResult==null?"":localResult.Warning.Length>0?localResult.Warning+" ":localResult.Engine+" · ")+(String.IsNullOrWhiteSpace(text)?"No text found. The image is available in the sidebar.":"Text is ready. Edit it, copy it, or choose a translation.")+(imageWarning==""?"":" "+imageWarning));}
            catch(OperationCanceledException){if(!closing){SetBusy(false,"Extraction canceled. Your image and previous text were kept."+(imageWarning.Length==0?"":" "+imageWarning));}}
            catch(Exception ex){if(!closing){SetBusy(false,"Extraction failed. Your image and previous text were kept."+(imageWarning.Length==0?"":" "+imageWarning));Notice(ex.Message,ex is CodexException?CodexDiagnostics.Title(((CodexException)ex).Issue):"Text extraction");}}
            finally{if(remove)TransientImages.Delete(path);}
        }
        async Task OpenImage(){if(busy)return;using(var dialog=new OpenFileDialog{Title="Choose an image to extract text",Filter="Images|*.png;*.jpg;*.jpeg;*.bmp;*.tif;*.tiff"}){if(dialog.ShowDialog(this)==DialogResult.OK)await ReadImage(dialog.FileName,false);}}
        async Task ClipboardImage(){if(busy)return;string p=null;try{if(!Clipboard.ContainsImage()){status.Text="No image on the clipboard. Copy a screenshot first.";return;}p=TempImage();using(var image=Clipboard.GetImage())image.Save(p,ImageFormat.Png);await ReadImage(p,true);}catch(Exception ex){Notice(ex.Message,"Clipboard");}finally{TransientImages.Delete(p);}}
        static string TempImage(){return TransientImages.Create();}
        async void CaptureRegion(){if(busy||capturing)return;string inputPath=null;capturing=true;Hide();await Task.Delay(250);try{if(closing)return;var area=SystemInformation.VirtualScreen;using(var desktop=new Bitmap(area.Width,area.Height)){using(var g=Graphics.FromImage(desktop))g.CopyFromScreen(area.Location,Point.Empty,area.Size);using(var picker=new RegionPicker(desktop,area,blue)){if(picker.ShowDialog()==DialogResult.OK){var selection=picker.Selected;var local=new Rectangle(selection.X-area.X,selection.Y-area.Y,selection.Width,selection.Height);inputPath=TempImage();var p=inputPath;using(var crop=desktop.Clone(local,PixelFormat.Format32bppArgb))crop.Save(p,ImageFormat.Png);Restore();await ReadImage(p,true);}else Restore();}}}catch(Exception ex){if(!closing){Restore();Notice(ex.Message,"Screenshot");}}finally{TransientImages.Delete(inputPath);capturing=false;}}
        async Task Translate(string language,string title){
            if(busy)return;var target=TranslationCatalog.Find(language);if(target!=null)SelectTranslationTarget(target);var text=source.Text;if(String.IsNullOrWhiteSpace(text)){status.Text="Add or extract some text first.";return;}
            SetBusy(true,"Translating to "+title+" with "+AiName+"…");
            try{var translated=await TranslateWithAi(text,language,operation.Token);if(closing)return;CommitTranslationResult(translated,text,target==null?language:target.Id,title);SetBusy(false,"Translation is ready.");}
            catch(OperationCanceledException){if(!closing){SetBusy(false,"Translation canceled. Previous text was kept.");}}
            catch(Exception ex){if(!closing){SetBusy(false,"Translation failed. Previous text was kept.");Notice(ex.Message,ex is CodexException?CodexDiagnostics.Title(((CodexException)ex).Issue):"Translation");}}
        }
